// 2026-08-26 改动逻辑：直接依据角色名称中的文字关键词标注物种，不读取或识别角色图片；
// 性别、年龄和气质沿用每个角色随名称保存的文字属性，并统一整理成四类 tags，供所有公共资产库入口筛选。
(function attachCharacterNameTags(library) {
  const speciesNameRules = [
    [/矮人/, "矮人"],
    [/机器人|机械哨兵|机械守卫|机械猎手|机械圣教卫士/, "机器人"],
    [/人鱼/, "人鱼"],
    [/史莱姆/, "史莱姆"],
    [/魔宠/, "魔宠"],
    [/精灵/, "精灵"],
    [/羽蛇神|邪灵|龙神|神灯|冥界|生灵之子/, "神灵"]
  ];

  Object.values(library.pages || {}).forEach((regions) => {
    Object.values(regions || {}).forEach((characters) => {
      (characters || []).forEach((character) => {
        const [rawGender = "", age = "", body = "", temperament = ""] = String(character.meta || "").split(" · ");
        const matchedSpecies = speciesNameRules.find(([pattern]) => pattern.test(character.name || ""));
        const species = matchedSpecies?.[1] || (body === "非人形" ? "非人类" : "人类");
        character.tags = {
          gender: rawGender === "中性" ? "其他" : rawGender,
          age,
          species,
          temperament
        };
      });
    });
  });
})(window.__VINA_XYQ_CHARACTER_LIBRARY__);
